// Zero-LLM Deterministic Heuristic Classifier
// Extracts cargo dimensions, weight, and routes from unstructured text or structured JSON

const raw = $input.first().json.body || $input.first().json;

// 1. Text extraction fallback if raw message text provided
let origin = raw.origin || raw.origin_query || "";
let destination = raw.destination || raw.destination_query || "";
let weight = parseFloat(raw.weight_mt || raw.weight || 0);
let height = parseFloat(raw.height_m || raw.height || 0);
let width = parseFloat(raw.width_m || raw.width || 0);
let length = parseFloat(raw.length_m || raw.length || 0);
let axles = parseInt(raw.axle_count || raw.axles || 0);

const text = (raw.text || raw.message || raw.description || "").toString();

if (text) {
  // Regex extraction for weight (e.g. 120MT, 85 tons, 95 MT)
  const weightMatch = text.match(/(\d+(?:\.\d+)?)\s*(?:MT|metric\s*tons?|tons?)/i);
  if (weightMatch && !weight) weight = parseFloat(weightMatch[1]);

  // Regex for height (e.g. 5.1m, 5.2 meters)
  const heightMatch = text.match(/(?:height|ht|h)[:\s]*(\d+(?:\.\d+)?)\s*m/i);
  if (heightMatch && !height) height = parseFloat(heightMatch[1]);

  // Regex for width (e.g. 4.2m width, w: 4.5m)
  const widthMatch = text.match(/(?:width|wd|w)[:\s]*(\d+(?:\.\d+)?)\s*m/i);
  if (widthMatch && !width) width = parseFloat(widthMatch[1]);

  // Regex for length (e.g. 24.5m length, l: 28m)
  const lengthMatch = text.match(/(?:length|len|l)[:\s]*(\d+(?:\.\d+)?)\s*m/i);
  if (lengthMatch && !length) length = parseFloat(lengthMatch[1]);

  // Port and Destination recognition
  if (/vizag|visakhapatnam/i.test(text)) origin = origin || "Visakhapatnam Port";
  if (/chennai|madras/i.test(text)) origin = origin || "Chennai Port";
  if (/jnpt|mumbai|nhava\s*sheva/i.test(text)) origin = origin || "JNPT Mumbai";
  if (/kolkata|calcutta|haldia/i.test(text)) origin = origin || "Kolkata Port";
  if (/paradip/i.test(text)) origin = origin || "Paradip Port";
  if (/mundra/i.test(text)) origin = origin || "Mundra Port";

  if (/raipur|bhilai/i.test(text)) destination = destination || "Raipur Logistics Hub";
  if (/nagpur|mihan/i.test(text)) destination = destination || "Nagpur Multimodal Hub";
  if (/hyderabad|secunderabad/i.test(text)) destination = destination || "Hyderabad Heavy Industrial";
  if (/jharsuguda|rourkela/i.test(text)) destination = destination || "Jharsuguda Industrial Hub";
  if (/jamshedpur|tatanagar/i.test(text)) destination = destination || "Jamshedpur Tata Steel Complex";
  if (/pune|chakan/i.test(text)) destination = destination || "Pune Chakan Auto Cluster";
  if (/bangalore|bengaluru/i.test(text)) destination = destination || "Bangalore Nelamangala Hub";
  if (/ahmedabad|sanand/i.test(text)) destination = destination || "Ahmedabad Sanand Hub";
}

// Defaults
origin = origin || "Visakhapatnam Port";
destination = destination || "Raipur Logistics Hub";
weight = weight || 85.0;
height = height || 5.1;
width = width || 4.2;
length = length || 24.5;
axles = axles || Math.max(6, Math.ceil((weight + 35) / 12.5));

// Cargo Category Classification
let cargoCategory = "STANDARD_ODC";
if (weight > 100) {
  cargoCategory = "HEAVY_LIFT_SUPER_LOAD";
} else if (width > 4.0 || height > 5.0) {
  cargoCategory = "WIDE_OVERHEAD_CRITICAL";
}

return [{
  json: {
    origin_query: origin,
    destination_query: destination,
    cargo_weight_mt: weight,
    cargo_height_m: height,
    cargo_width_m: width,
    cargo_length_m: length,
    axle_count: axles,
    cargo_category: cargoCategory,
    allow_bypasses: true,
    client_id: raw.client_id || "SEALAND_INGESTION_SENSOR",
    survey_id: raw.survey_id || ("SURVEY-N8N-" + Date.now().toString(36).toUpperCase())
  }
}];

